import { writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import { createDevHome } from './home.js';

export function runDevInit(targetPath: string, env: NodeJS.ProcessEnv = process.env): string {
  if (!targetPath) {
    throw new Error('Usage: npm run dev:init -- <path>');
  }

  const factoryHome = createDevHome(targetPath, env);
  const configPath = join(factoryHome, 'config.yaml');
  const contents = [
    '# Generated by npm run dev:init',
    'version: 1',
    '',
  ].join('\n');

  writeFileSync(configPath, contents, 'utf8');
  return configPath;
}

function runCli(argv: string[], env: NodeJS.ProcessEnv): void {
  const configPath = runDevInit(argv[0] ?? '', env);
  process.stdout.write(`Created ${configPath}\n`);
}

const modulePath = fileURLToPath(import.meta.url);
const invokedPath = process.argv[1] ? resolve(process.argv[1]) : '';
if (invokedPath && pathToFileURL(invokedPath).href === pathToFileURL(modulePath).href) {
  try {
    runCli(process.argv.slice(2), process.env);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${message}\n`);
    process.exitCode = 1;
  }
}
